    <el-card shadow="never" class="filter-card"><el-form :inline="true" :model="query"><el-form-item><el-select v-model="query.companyDeptId" clearable placeholder="全部授权公司" style="width:190px"><el-option v-for="c in data.companies" :key="c.companyDeptId" :label="c.companyName" :value="c.companyDeptId" /></el-select></el-form-item><el-form-item><el-select v-model="query.projectId" clearable filterable placeholder="全部本人项目" style="width:220px"><el-option v-for="p in filteredProjects" :key="p.projectId" :label="`${p.projectName} · ${p.initiatorName}`" :value="p.projectId" /></el-select></el-form-item><el-form-item><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">今天</el-button></el-form-item></el-form></el-card>
