abel="项目投入" width="110" align="right"><template #default="{row}"><span v-if="row.costPolicyVersion==='ACTUAL_WORK_V1'">{{ workHours(row.workMinutes) }}</span><span v-else-if="row.appliedPercent!=null">{{ row.appliedPercent }}%</span><small>{{ row.costPolicyVersion==='ACTUAL_WORK_V1'?(row.workMinutes==null?'尚无已确认工作':'已确认工作'):(inputSourceLabel[row.inputSource] || '未设置') }}</small></template></el-table-column><el-table-column label="当日成本" width="115" align="right"><template #default="{row}"><b>{{ row.personnelCost==null?'待计价 / 未记录':money(row.personnelCost) }}</b></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="costStatusTone[row.costStatus]">{{ costStatusLabel[row.costStatus] || row.costStatus }}</el-tag></template></el-table-column><el-table-column label="处理" width="105"><template #default="{row}"><el-button v-if="row.costStatus==='MISSING_REGION'" link type="primary" @click="openStaffProfile(row)">设置国家</el-button><el-button v-else-if="['MISSING_COST','LEGACY_COST','PENDING_COST'].includes(row.costStatus)" link type="primary" @click="openStaffCost(row)">设置成本</el-button><el-button v-else-if="['MISSING_ALLOCATION','MISSING_ACTUAL'].includes(row.costStatus)" link type="primary" @click="openAllocation(row)">查看项目</el-button><span v-else>—</span></template></el-table-column></el-table></el-card>
    <el-card shadow="never" class="section-card"><div class="section-head"><div><h2>项目日结果</h2><p>每次确认、冲销或手动重算都会生成新版本，点击可查看计算分项。</p></div><el-button v-hasPermi="['business:accounting:recalculate']" @click="openRecalculate">手动重算</el-button></div><el-table :data="data.results" @row-click="openResult" class="click-table"><el-table-column prop="bizDate" label="日期" width="105"/><el-table-column label="项目" min-width="190"><template #default="{row}"><b>{{ row.projectName }}</b><small>{{ row.companyName }} · {{ row.initiatorName }}立项</small></template></el-table-column><el-table-column label="收入" align="right"><template #default="{row}">{{ money(row.revenueAmount) }}</template></el-table-column><el-table-column label="业务成本" align="right"><template #default="{row}">{{ money(row.costAmount) }}</template></el-table-column><el-table-column label="人员成本" align="right"><template #default="{row}">{{ row.personnelCost==null?'待计价 / 未记录':money(row.personnelCost) }}</template></el-table-column><el-table-column label="项目奖金" align="right"><template #default="{row}">{{ money(row.bonusCost) }}</template></el-table-column><el-table-column label="经营结果" align="right"><template #default="{row}"><b :class="Number(row.profitAmount)<0?'red':'green'">{{ signed(row.profitAmount) }}</b></template></el-table-column><el-table-column label="版本" width="70"><template #default="{row}">v{{ row.resultVersion }}</template></el-table-column></el-table></el-card>
    <el-card shadow="never" class="section-card"><div class="section-head"><div><h2>收支流水</h2><p>{{ isBoss?'草稿可确认入账或退回修改；已确认流水只允许冲销。':'已退回的收支可根据原因修改并重新提交。' }}</p></div></div><el-table :data="data.facts"><el-table-column prop="bizDate" label="日期" width="105"/><el-table-column label="项目" min-width="170"><template #default="{row}">{{ row.projectName }}<small>{{ row.companyName }}</small></template></el-table-column><el-table-column prop="categoryName" label="类别"/><el-table-column prop="description" label="说明" min-width="180"/><el-table-column label="金额/数值" align="right"><template #default="{row}"><b>{{ row.factKind==='VALUE'?`${row.quantity} ${row.unit||''}`:`${signed(row.amount)} ${row.currency||''}` }}</b></template></el-table-column><el-table-column label="状态" min-width="135"><template #default="{row}"><el-tag :type="statusTone[row.status]">{{ statusLabel[row.status] || row.status }}</el-tag><small v-if="row.status==='RETURNED'" class="return-reason">原因：{{ row.returnReason }}</small></template></el-table-column><el-table-column label="操作" min-width="210"><template #default="{row}"><el-button v-if="isBoss||row.sourceDomain==='HR_INCENTIVE'" link type="primary" @click="openFact(row,true)">查看详情</el-button><el-button v-else-if="row.sourceDomain!=='HR_INCENTIVE' && isFactAccountingOpen(row) && ['DRAFT','RETURNED'].includes(row.status)" link @click="openFact(row)">{{ row.status==='RETURNED'?'修改并重新提交':'编辑' }}</el-button><el-button v-if="canReviewFact(row)&&isFactAccountingOpen(row)&&row.status==='DRAFT'" link type="success" @click="confirmFact(row)">确认入账</el-button><el-button v-if="canReviewFact(row)&&isFactAccountingOpen(row)&&row.status==='DRAFT'" link type="warning" @click="returnFact(row)">退回修改</el-button><el-button v-if="canReviewFact(row)&&isFactAccountingOpen(row)&&row.status==='CONFIRMED'" link type="danger" @click="reverseFact(row)">冲销</el-button></template></el-table-column></el-table></el-card>

    <el-dialog v-model="factDialog" :title="factReadOnly?'收支流水详情':factForm.factId?'编辑收支草稿':'录入每日收支'" width="min(680px,94vw)" append-to-body><el-alert :title="factReadOnly?'当前为查看详情，所有数据均为只读状态。':'保存后先进入草稿；老板确认后才会计入正式日报。'" type="info" :closable="false" show-icon/><el-alert v-if="factForm.sourceDomain==='HR_INCENTIVE'" title="此成本来自已核准奖励单，不能修改金额或来源；退回后请在奖金激励中续办。成本入账不代表已经发放。" :closable="false"/><el-alert v-if="factForm.status==='RETURNED'" class="return-alert" :title="`退回原因：${factForm.returnReason||'未填写'}`" :description="`${factForm.returnedUserName||'老板'} 于 ${factForm.returnedTime||'—'} 退回，修改保存后将重新进入待确认。`" type="warning" :closable="false" show-icon/><el-form :model="factForm" :disabled="factReadOnly" label-width="92px" class="dialog-form"><el-form-item label="归属项目" required><el-select v-model="factForm.projectId" :disabled="factReadOnly||!!factForm.factId" filterable style="width:100%" @change="projectChanged"><el-option v-for="p in factProjectOptions" :key="p.projectId" :label="`${p.projectName} · ${p.companyName||'未设置公司'}`" :value="p.projectId" /></el-select></el-form-item><el-form-item label="业务日期" required><el-date-picker v-model="factForm.bizDate" :disabled-date="disabledFactDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="收支类别" required><el-select v-model="factForm.categoryId" style="width:100%"><el-option-group v-for="group in categoryGroups" :key="group.kind" :label="group.label"><el-option v-for="c in group.items" :key="c.categoryId" :label="c.categoryName" :value="c.categoryId" /></el-option-group></el-select></el-form-item><template v-if="selectedCategory?.factKind==='VALUE'"><el-form-item label="成果数值" required><el-input-number v-model="factForm.quantity" :precision="4" style="width:100%" /></el-form-item><el-form-item label="单位"><el-input v-model="factForm.unit" /></el-form-item></template><template v-else><el-form-item label="金额" required><el-input-number v-model="factForm.amount" :precision="4" style="width:100%" /></el-form-item><el-form-item label="币种"><el-input v-model="factForm.currency" maxlength="3" /></el-form-item></template><el-form-item label="收支说明" required><el-input v-model="factForm.description" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item><el-form-item label="对方单位"><el-input v-model="factForm.counterparty" /></el-form-item><el-form-item label="凭证附件"><business-file-upload v-if="factReadOnly" :model-value="factForm.attachmentUrls" :project-id="factForm.projectId" disabled :drag="false" :is-show-tip="false"/><business-file-upload v-else v-model="factForm.attachmentUrls" :project-id="factForm.projectId" /></el-form-item><el-form-item label="备注"><el-input v-model="factForm.remark" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="factDialog=false">{{ factReadOnly?'关闭':'取消' }}</el-button><el-button v-if="!factReadOnly" type="primary" :disabled="!canWriteFactProject" :loading="saving" @click="saveFact">{{ factForm.status==='RETURNED'?'修改并重新提交':'保存草稿' }}</el-button></template></el-dialog>
    <el-dialog v-model="recalcDialog" title="重算项目日结果" width="min(500px,94vw)" append-to-body><el-form :model="recalcForm" label-width="90px"><el-form-item label="项目" required><el-select v-model="recalcForm.projectId" filterable style="width:100%"><el-option v-for="p in writableProjects" :key="p.projectId" :label="p.projectName" :value="p.projectId" /></el-select></el-form-item><el-form-item label="业务日期" required><el-date-picker v-model="recalcForm.bizDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></el-form><template #footer><el-button @click="recalcDialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!canRecalculateProject" @click="saveRecalculate">开始重算</el-button></template></el-dialog>
    <el-drawer v-model="resultDrawer" title="项目日结果计算明细" size="min(760px,96vw)" append-to-body><template v-if="resultDetail"><div class="result-title"><div><b>{{ resultDetail.projectName }}</b><span>{{ resultDetail.bizDate }} · v{{ resultDetail.resultVersion }}</span></div><strong :class="Number(resultDetail.profitAmount)<0?'red':'green'">{{ signed(resultDetail.profitAmount) }}</strong></div><el-alert :title="resultDetail.calculationDetail" type="info" :closable="false"/><el-table :data="resultDetail.items" class="item-table"><el-table-column prop="componentName" label="计算分项"/><el-table-column label="金额" align="right"><template #default="{row}">{{ signed(row.amount) }}</template></el-table-column><el-table-column prop="calculationDetail" label="来源说明" min-width="190"/></el-table><section class="personnel-detail">
  <div class="personnel-title"><div><h3>人员成本明细</h3><p>实际工作按已确认小时或人天计价；下表展示当时保存的核算依据。</p></div><b>{{ money(resultDetail.personnelCost) }} {{ resultDetail.currency||'CNY' }}</b></div>
  <el-table v-if="personnelDetailRows.length" :data="personnelDetailRows" size="small">
    <el-table-column prop="componentName" label="人员" min-width="100" />
    <el-table-column label="投入与来源" min-width="190"><template #default="{row}"><b>{{ row.workText }}</b><small>{{ row.sourceText }}</small></template></el-table-column>
    <el-table-column v-if="resultDetail.rawCostVisible===true" prop="rateText" label="内部费率快照" min-width="210" />
    <el-table-column label="核算金额" min-width="120" align="right"><template #default="{row}"><b>{{ money(row.amount) }}</b></template></el-table-column>
    <el-table-column prop="explanation" label="计算依据" min-width="250" />
  </el-table>
  <el-empty v-else description="本日没有已计价人员成本分项；未记录实际或待计价情况请查看人员成本核算。" :image-size="70" />
</section></template></el-drawer>
  </div>
</template>

<script setup name="BusinessAccounting">
import {ElMessage,ElMessageBox} from 'element-plus'
import {confirmBusinessOperatingFact,getBusinessAccountingDashboard,getBusinessDailyResult,getBusinessPersonnelCostOverview,recalculateBusinessProjectDay,returnBusinessOperatingFact,reverseBusinessOperatingFact,saveBusinessOperatingFact} from '@/api/business/accounting'
import { repriceProjectWork } from '@/api/business/projectWork'
import useUserStore from '@/store/modules/user'
import { useBusinessRefreshOnReactivated } from '@/utils/businessRefresh'
import BusinessSettlementPanel from '@/components/BusinessSettlementPanel/index.vue'
import { isSeparatedDelivery, isDeliveryEnded, projectAccountingState } from '@/utils/businessProjectState'
const today=()=>{const now=new Date();const local=new Date(now.getTime()-now.getTimezoneOffset()*60000);return local.toISOString().slice(0,10)}
const route=useRoute()
const router=useRouter()
const userStore=useUserStore()
function routeId(value){if(typeof value!=='string'||!/^\d+$/.test(value))return null;const id=Number(value);return Number.isSafeInteger(id)&&id>0?id:null}
function routeDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return today();const parsed=new Date(`${value}T00:00:00Z`);return !Number.isNaN(parsed.getTime())&&parsed.toISOString().slice(0,10)===value?value:today()}
const query=reactive({companyDeptId:routeId(route.query.companyDeptId),projectId:routeId(route.query.projectId)}),dates=ref([routeDate(route.query.dateFrom),routeDate(route.query.dateTo)]),data=reactive({summary:{},results:[],facts:[],companies:[],projects:[],categories:[]}),personnel=reactive({rows:[],personnelCost:0,readyCount:0,issueCount:0,overAllocatedCount:0}),issuesOnly=ref(false),saving=ref(false)
const factDialog=ref(false),factReadOnly=ref(false),factForm=reactive({}),recalcDialog=ref(false),recalcForm=reactive({}),resultDrawer=ref(false),resultDetail=ref(null)
const summary=computed(()=>data.summary||{}),filteredProjects=computed(()=>query.companyDeptId?data.projects.filter(p=>Number(p.companyDeptId)===Number(query.companyDeptId)):data.projects)
const writableProjects=computed(()=>data.projects.filter(project=>projectAccountingState(project)==='OPEN'))
const factProjectOptions=computed(()=>factReadOnly.value?data.projects:writableProjects.value)
const canRecalculateProject=computed(()=>writableProjects.value.some(project=>Number(project.projectId)===Number(recalcForm.projectId)))
const selectedProject=computed(()=>data.projects.find(p=>Number(p.projectId)===Number(query.projectId))||{projectId:query.projectId})
const repricing=ref(false),loadingData=ref(false),loadedProjectId=ref(null)
let loadSequence=0
const selectedActualProject=computed(()=>!!query.projectId&&selectedProject.value.costPolicyVersion==='ACTUAL_WORK_V1')
const hasIncompleteCosts=computed(()=>Number(data.pendingCostCount)>0||personnel.hasUnpricedOrMissingWork===true)
const pricingNotice=computed(()=>Number(data.pendingCostCount)>0
  ? `当前查询范围有 ${data.pendingCostCount} 条已确认工作待计价；下列金额为已核算部分，不能视为完整成本或最终利润。补充有效费率后，可选择对应项目重试计价。`
  : '当前核算日有人员未记录实际工作；缺失工作量不是零投入，人员成本和经营结果仍可能不完整。')
const canRetryPricing=computed(()=>selectedActualProject.value&&Number(loadedProjectId.value)===Number(query.projectId)&&!loadingData.value&&projectAccountingState(selectedProject.value)==='OPEN')
const factProject=computed(()=>data.projects.find(p=>Number(p.projectId)===Number(factForm.projectId)))
const canWriteFactProject=computed(()=>!!factProject.value&&projectAccountingState(factProject.value)==='OPEN')
function canReviewFact(fact){if(!isBoss.value)return false;if(fact.sourceDomain!=='HR_INCENTIVE')return true;const p=data.projects.find(p=>Number(p.projectId)===Number(fact.projectId));return Number(p?.sponsorOwnerUserId||p?.initiatorUserId)===Number(userStore.id)}
function isFactAccountingOpen(fact){const project=data.projects.find(p=>Number(p.projectId)===Number(fact.projectId));return projectAccountingState(project||{...fact,status:fact.projectStatus})==='OPEN'}
function disabledFactDate(date){const project=factProject.value,value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,10);if(!project||value>today())return true;if(isSeparatedDelivery(project)&&isDeliveryEnded(project)){const end=String(project.actualEndDate||'').slice(0,10);return !end||value>end}return false}
const isBoss=computed(()=>userStore.roles.includes('admin')||userStore.permissions.includes('*:*:*')||userStore.permissions.includes('business:boss:view'))
const selectedCategory=computed(()=>data.categories.find(c=>Number(c.categoryId)===Number(factForm.categoryId)))
const categoryGroups=computed(()=>['REVENUE','COST','ADJUSTMENT','VALUE'].map(kind=>({kind,label:{REVENUE:'收入',COST:'成本费用',ADJUSTMENT:'核算调整',VALUE:'非金额成果'}[kind],items:data.categories.filter(c=>c.factKind===kind)})).filter(g=>g.items.length))
const statusLabel={DRAFT:'待确认',RETURNED:'已退回',CONFIRMED:'已确认',REVERSED:'已冲销',VOIDED:'已作废'},statusTone={DRAFT:'warning',RETURNED:'danger',CONFIRMED:'success',REVERSED:'warning',VOIDED:'info'}
const costStatusLabel={MISSING_ACTUAL:'未记录实际',PENDING_COST:'待计价',READY:'核算就绪',LEAVE:'今日请假',MISSING_REGION:'未设置国家',MISSING_COST:'未设置成本',LEGACY_COST:'需更新成本',MISSING_ALLOCATION:'未设置投入',OVER_ALLOCATED:'投入超100%'}
const costStatusTone={MISSING_ACTUAL:'info',PENDING_COST:'warning',READY:'success',LEAVE:'info',MISSING_REGION:'danger',MISSING_COST:'danger',LEGACY_COST:'warning',MISSING_ALLOCATION:'warning',OVER_ALLOCATED:'danger'}
const inputSourceLabel={ACTUAL_WORK:'已确认工作',ACTUAL_WORK_V1:'已确认工作',PLAN:'计划投入',ACTUAL:'确认实际',LEAVE:'今日请假'}
const visiblePersonnelRows=computed(()=>issuesOnly.value?(personnel.rows||[]).filter(row=>!['READY','LEAVE'].includes(row.costStatus)):(personnel.rows||[]))
const personnelDetailRows=computed(()=>(resultDetail.value?.personnelItems||[]).map(item=>{
  const rawVisible=resultDetail.value?.rawCostVisible===true
  let basis=null
  if(rawVisible){try{const parsed=JSON.parse(item.calculationDetail);if(parsed?.costPolicyVersion==='ACTUAL_WORK_V1')basis=parsed}catch{/* 历史计算依据为文本，按原快照展示。 */}}
  if(!basis)return {...item,workText:item.workMinutes!=null?workHours(item.workMinutes):item.appliedPercent!=null?`${item.appliedPercent}%`:'以保存的依据为准',sourceText:inputSourceLabel[item.inputSource]||'已保存核算快照',rateText:'见保存的计算依据',explanation:rawVisible?(item.calculationDetail||'未保存计算说明'):'已保存项目成本依据；内部费率需另获成本查看权限'}
  const quantity=basis.inputQuantity,unit=basis.inputUnit,rate=basis.rateSnapshot||{},currency=rate.currency||resultDetail.value.currency||''
  let rateText='未使用内部费率'
  if(rate.unitCost!=null){const label={HOURLY:'小时',DAILY:'人天',MONTHLY:'月'}[rate.costMode]||'单位';rateText=`${money(rate.unitCost)} ${currency} / ${label}`;if(rate.costMode==='MONTHLY'&&rate.standardWorkDays!=null)rateText+=`；月标准 ${rate.standardWorkDays} 天`;if(['DAILY','MONTHLY'].includes(rate.costMode)&&rate.rateMinutesPerDay!=null)rateText+=`；1 人天 = ${workHours(rate.rateMinutesPerDay)}`}
  return {...item,workText:quantity!=null&&['HOUR','DAY'].includes(unit)?`${quantity} ${unit==='DAY'?'人天':'小时'}`:workHours(basis.workMinutes),sourceText:`工作记录 #${basis.sourceEntryId??'—'} · 修订 ${basis.sourceRevision??'—'}`,rateText,explanation:basis.formula==='CORRECTION_WITHDRAWAL'?'撤回更正记录，已确认工作量为零':`已确认 ${workHours(basis.workMinutes)}${unit==='DAY'&&basis.minutesPerDay!=null?`；工作量换算 1 人天 = ${workHours(basis.minutesPerDay)}`:''}；按该记录的有效费率核算，金额保留 2 位小数。`}
}))
const money=v=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4}),signed=v=>`${v!=null&&Number(v)>0?'+':''}${money(v)}`
const regionLabel=value=>value==='VN'?'越南':value==='CN'?'中国':value||'—'
const workHours=value=>value==null?'未记录':`${Number((Number(value)/60).toFixed(4))} 小时`
async function load(){const sequence=++loadSequence,params={...query,dateFrom:dates.value?.[0],dateTo:dates.value?.[1]};loadingData.value=true;try{const [dashboardRes,personnelRes]=await Promise.all([getBusinessAccountingDashboard(params),getBusinessPersonnelCostOverview({...query,bizDate:dates.value?.[1]||today()})]);if(sequence!==loadSequence)return;Object.assign(data,{pendingCostCount:0},dashboardRes.data||{});Object.assign(personnel,{hasUnpricedOrMissingWork:false},personnelRes.data||{});loadedProjectId.value=params.projectId}finally{if(sequence===loadSequence)loadingData.value=false}}
async function retryPricing(){if(repricing.value)return;if(!canRetryPricing.value)return ElMessage.warning('请先查询一个核算开放的实际工作项目');const projectId=query.projectId;repricing.value=true;try{const response=await repriceProjectWork(projectId);await load();const pending=Number(response.data?.pendingCostCount||0),processed=Number(response.data?.processedEvents||0);if(pending>0)ElMessage.warning(`已重试 ${processed} 条工作计价事件，仍有 ${pending} 条待计价，请核对有效费率、币种和生效日期`);else ElMessage.success(processed>0?'工作成本计价已完成，核算结果已刷新':'当前没有待处理的工作计价事件，核算结果已刷新')}catch{/* 请求拦截器统一展示接口错误，避免重复提示。 */}finally{repricing.value=false}}
function reset(){Object.assign(query,{companyDeptId:null,projectId:null});dates.value=[today(),today()];load()}
function openFact(row={},readOnly=false){const project=data.projects.find(value=>Number(value.projectId)===Number(row.projectId)),defaultProject=writableProjects.value.find(value=>Number(value.projectId)===Number(query.projectId));factReadOnly.value=readOnly||row.sourceDomain==='HR_INCENTIVE'||!!row.factId&&projectAccountingState(project)!=='OPEN';Object.keys(factForm).forEach(k=>delete factForm[k]);Object.assign(factForm,{factId:null,projectId:defaultProject?.projectId||null,bizDate:today(),categoryId:null,amount:null,quantity:null,currency:defaultProject?.currency||'CNY',unit:'',description:'',counterparty:'',attachmentUrls:'',remark:'',version:null,...row});factDialog.value=true}
function projectChanged(id){const p=data.projects.find(x=>Number(x.projectId)===Number(id));if(p)factForm.currency=p.currency||'CNY'}
async function saveFact(){if(factReadOnly.value)return;if(!canWriteFactProject.value)return ElMessage.warning('该项目核算不可写，请刷新核对状态');if(!factForm.projectId||!factForm.categoryId||!factForm.bizDate)return ElMessage.warning('请完整选择项目、日期和类别');if(!factForm.description?.trim())return ElMessage.warning('请填写收支说明');const wasReturned=factForm.status==='RETURNED';saving.value=true;try{await saveBusinessOperatingFact(factForm);factDialog.value=false;await load();ElMessage.success(wasReturned?'已修改并重新提交，等待老板确认':'收支草稿已保存')}finally{saving.value=false}}
async function confirmFact(row){await ElMessageBox.confirm('确认后将计入正式日报，不能直接修改，确定吗？','确认入账',{type:'warning'});await confirmBusinessOperatingFact(row.factId);await load();ElMessage.success('已确认入账并生成日结果')}
async function returnFact(row){const {value}=await ElMessageBox.prompt('请说明收支数据或凭证需要修改的内容','退回收支修改',{inputValidator:v=>!!v?.trim()||'必须填写退回原因',inputAttributes:{maxlength:500},type:'warning'});await returnBusinessOperatingFact(row.factId,{reason:value.trim()});await load();ElMessage.success('已退回提交人修改')}
async function reverseFact(row){const {value}=await ElMessageBox.prompt('请填写冲销原因','冲销已确认流水',{inputValidator:v=>!!v?.trim()||'必须填写冲销原因',type:'warning'});await reverseBusinessOperatingFact(row.factId,{reason:value});await load();ElMessage.success('已冲销并重新生成日结果')}
function openRecalculate(){const project=writableProjects.value.find(value=>Number(value.projectId)===Number(query.projectId));Object.assign(recalcForm,{projectId:project?.projectId||null,bizDate:dates.value?.[1]||today()});recalcDialog.value=true}
async function saveRecalculate(){if(!canRecalculateProject.value||!recalcForm.bizDate)return ElMessage.warning('请选择核算开放的项目和日期');saving.value=true;try{await recalculateBusinessProjectDay(recalcForm);recalcDialog.value=false;await load();ElMessage.success('项目日结果已生成新版本')}finally{saving.value=false}}
async function openResult(row){resultDetail.value=(await getBusinessDailyResult(row.resultId)).data;resultDrawer.value=true}
function openStaffCost(row){router.push({path:'/finance/cost-policies',query:{userId:row.userId}})}
function openStaffProfile(row){router.push({path:'/business/staff',query:{userId:row.userId,action:'edit'}})}
function openAllocation(row){router.push({path:'/business/projects',query:{id:row.projectId,tab:'operating'}})}
watch(()=>[route.path,route.query.companyDeptId,route.query.projectId,route.query.dateFrom,route.query.dateTo],async()=>{
  if(!['/finance/accounting','/business/accounting'].includes(route.path))return
  Object.assign(query,{companyDeptId:routeId(route.query.companyDeptId),projectId:routeId(route.query.projectId)})
  dates.value=[routeDate(route.query.dateFrom),routeDate(route.query.dateTo)]
  Object.assign(data,{summary:{},results:[],facts:[],pendingCostCount:0})
  Object.assign(personnel,{rows:[],personnelCost:null,hasUnpricedOrMissingWork:false,readyCount:0,issueCount:0,overAllocatedCount:0})
  loadedProjectId.value=null
  try{await load()}catch{/* 请求错误由统一拦截器展示。 */}
},{immediate:true})
useBusinessRefreshOnReactivated(()=>loadingData.value?undefined:load())
</script>

