p:18px}.result-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;padding:16px;border-radius:10px;background:#f5f8fa}.result-title b,.result-title span{display:block}.result-title span{margin-top:5px;color:#8692a0}.result-title strong{font-size:24px}.item-table{margin-top:14px}.personnel-detail{margin-top:22px;padding-top:18px;border-top:1px solid #e4e8ed}.personnel-title{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:12px}.personnel-title h3{margin:0;font-size:17px}.personnel-title p{margin:5px 0 0;color:#8491a0;font-size:12px}.personnel-title>b{color:#2c6f65}@media(max-width:1180px){.summary-grid{grid-template-columns:repeat(4,1fr)}}@media(max-width:760px){.accounting-page{padding:14px}.hero{align-items:flex-start;flex-direction:column;gap:16px;padding:22px}.hero .el-button{width:100%}.summary-grid{grid-template-columns:repeat(2,1fr)}.summary-grid article:last-child{grid-column:span 2}.filter-card :deep(.el-form-item){display:flex;margin-right:0}.filter-card :deep(.el-select),.filter-card :deep(.el-date-editor){width:100%!important}.section-head{align-items:flex-start;flex-direction:column;gap:10px}.personnel-tools{width:100%;justify-content:space-between}.personnel-summary{grid-template-columns:repeat(2,1fr)}.personnel-title{align-items:flex-start;flex-direction:column;gap:8px}}
.pricing-notice{display:flex;align-items:center;gap:12px;margin-top:14px}.pricing-notice .el-alert{flex:1}.pricing-notice>.el-button{flex-shrink:0}.personnel-detail :deep(.el-table .cell){white-space:normal;line-height:1.6}@media(max-width:760px){.pricing-notice{align-items:stretch;flex-direction:column}.pricing-notice>.el-button{width:100%}}</style>
